class CircuitBreaker {
  private failures = 0;
  private state: "closed" | "open" | "half-open" = "closed";
  private nextAttempt = 0;

  constructor(
    private threshold = 5,
    private cooldown = 30_000
  ) {}

  async call<T>(fn: () => Promise<T>): Promise<T> {
    if (this.state === "open") {
      if (Date.now() < this.nextAttempt) throw new Error("Circuit OPEN");
      this.state = "half-open";
    }
    try {
      const result = await fn();
      this.failures = 0;
      this.state = "closed";
      return result;
    } catch (err) {
      this.failures++;
      if (this.failures >= this.threshold) {
        this.state = "open";
        this.nextAttempt = Date.now() + this.cooldown;
      }
      throw err;
    }
  }
}

#include <stdatomic.h>
#include <stdlib.h>
#include <stdbool.h>

struct Node {
    int data;
    struct Node* next;
};

struct Stack {
    _Atomic(struct Node*) head;
};

/* Initialize the atomic head pointer */
void init_stack(struct Stack* stack) {
    atomic_init(&stack->head, NULL);
}

/* Thread-safe, lock-free push operation using atomic CAS loop */
void push(struct Stack* stack, int val) {
    struct Node* new_node = malloc(sizeof(struct Node));
    new_node->data = val;

    struct Node* old_head = atomic_load(&stack->head);
    do {
        new_node->next = old_head;
        /*
         * Compares the current head with old_head:
         * If they match, head is updated to new_node and returns true.
         * If they differ, old_head is updated to the actual current head and returns false,
         * causing the loop to retry with the updated reference.
         */
    } while (!atomic_compare_exchange_weak(&stack->head, &old_head, new_node));
}

/* Thread-safe, lock-free pop operation */
bool pop(struct Stack* stack, int* val) {
    struct Node* old_head = atomic_load(&stack->head);
    struct Node* new_head;

    do {
        if (old_head == NULL) {
            return false; /* Stack is empty */
        }
        new_head = old_head->next;
    } while (!atomic_compare_exchange_weak(&stack->head, &old_head, new_head));

    *val = old_head->data;

    /*
     * WARNING on Memory Reclamation:
     * Direct free() in high-performance C applications can lead to the ABA problem.
     * If Thread 1 reads old_head (A), then pauses, and Thread 2 pops A, pops B,
     * frees both, and pushes A back (reusing the same address), when Thread 1 resumes,
     * its CAS will succeed but new_head (B) will point to a corrupted, freed memory address.
     * In production, use Hazard Pointers or Epoch-Based Reclamation.
     */
    free(old_head);
    return true;
}

package main

import (
    "context"
    "errors"
    "net"
    "sync"
    "time"
)

type Conn interface {
    Ping() error
    Close() error
    IsClosed() bool
}

type mockConn struct {
    netConn   net.Conn
    createdAt time.Time
    closed    bool
}

func (c *mockConn) Ping() error      { return nil }
func (c *mockConn) Close() error     { c.closed = true; return nil }
func (c *mockConn) IsClosed() bool   { return c.closed }

type PoolConfig struct {
    MinIdle     int
    MaxPoolSize int
    MaxLifetime time.Duration
    DialTimeout time.Duration
}

type Pool struct {
    config PoolConfig
    conns  chan *mockConn
    mu     sync.Mutex
    active int
}

func NewPool(config PoolConfig) (*Pool, error) {
    p := &Pool{
        config: config,
        conns:  make(chan *mockConn, config.MaxPoolSize),
    }
    for i := 0; i < config.MinIdle; i++ {
        conn, err := p.dial()
        if err == nil {
            p.conns <- conn
            p.active++
        }
    }
    go p.supervisor()
    return p, nil
}

func (p *Pool) dial() (*mockConn, error) {
    return &mockConn{
        createdAt: time.Now(),
    }, nil
}

func (p *Pool) Acquire(ctx context.Context) (Conn, error) {
    p.mu.Lock()
    if len(p.conns) == 0 && p.active < p.config.MaxPoolSize {
        conn, err := p.dial()
        if err == nil {
            p.active++
            p.mu.Unlock()
            return conn, nil
        }
    }
    p.mu.Unlock()

    select {
    case conn := <-p.conns:
        if time.Since(conn.createdAt) > p.config.MaxLifetime {
            conn.Close()
            p.mu.Lock()
            p.active--
            p.mu.Unlock()
            return p.Acquire(ctx)
        }
        return conn, nil
    case <-ctx.Done():
        return nil, ctx.Err()
    }
}

func (p *Pool) Release(conn Conn) {
    mc, ok := conn.(*mockConn)
    if !ok || mc.IsClosed() {
        p.mu.Lock()
        p.active--
        p.mu.Unlock()
        return
    }

    select {
    case p.conns <- mc:
    default:
        mc.Close()
        p.mu.Lock()
        p.active--
        p.mu.Unlock()
    }
}

func (p *Pool) supervisor() {
    ticker := time.NewTicker(30 * time.Second)
    for range ticker.C {
        p.mu.Lock()
        numIdle := len(p.conns)
        for i := 0; i < numIdle; i++ {
            select {
            case conn := <-p.conns:
                if time.Since(conn.createdAt) > p.config.MaxLifetime || conn.Ping() != nil {
                    conn.Close()
                    p.active--
                } else {
                    p.conns <- conn
                }
            default:
                break
            }
        }
        p.mu.Unlock()
    }
}

package main

import (
    "fmt"
    "hash/fnv"
    "sort"
    "strconv"
)

type HashRing struct {
    vnodes      int
    ring        []uint32
    nodeMap     map[uint32]string
    physicalMap map[string]bool
}

func NewHashRing(vnodes int) *HashRing {
    return &HashRing{
        vnodes:      vnodes,
        nodeMap:     make(map[uint32]string),
        physicalMap: make(map[string]bool),
    }
}

func (h *HashRing) hash(key string) uint32 {
    hasher := fnv.New32a()
    hasher.Write([]byte(key))
    return hasher.Sum32()
}

func (h *HashRing) AddNode(node string) {
    if h.physicalMap[node] {
        return
    }
    h.physicalMap[node] = true

    for i := 0; i < h.vnodes; i++ {
        vnodeName := node + "#" + strconv.Itoa(i)
        vnodeHash := h.hash(vnodeName)
        h.ring = append(h.ring, vnodeHash)
        h.nodeMap[vnodeHash] = node
    }
    sort.Slice(h.ring, func(i, j int) bool {
        return h.ring[i] < h.ring[j]
    })
}

func (h *HashRing) RemoveNode(node string) {
    if !h.physicalMap[node] {
        return
    }
    delete(h.physicalMap, node)

    newRing := make([]uint32, 0, len(h.ring)-h.vnodes)
    for _, vnodeHash := range h.ring {
        if h.nodeMap[vnodeHash] == node {
            delete(h.nodeMap, vnodeHash)
        } else {
            newRing = append(newRing, vnodeHash)
        }
    }
    h.ring = newRing
}

func (h *HashRing) GetNode(key string) string {
    if len(h.ring) == 0 {
        return ""
    }

    keyHash := h.hash(key)

    idx := sort.Search(len(h.ring), func(i int) bool {
        return h.ring[i] >= keyHash
    })

    if idx == len(h.ring) {
        idx = 0
    }

    return h.nodeMap[h.ring[idx]]
}

func main() {
    hr := NewHashRing(50)
    hr.AddNode("node-a")
    hr.AddNode("node-b")
    hr.AddNode("node-c")

    keys := []string{"user_123", "session_abc", "image_999"}
    for _, key := range keys {
        fmt.Printf("Key '%s' routes to: %s\n", key, hr.GetNode(key))
    }
}

package main

import (
    "fmt"
    "sync"
    "time"
)

type WritePayload struct {
    Key   string
    Value string
}

type Hint struct {
    TargetNode string
    Payload    WritePayload
    Timestamp  time.Time
}

type Node struct {
    Name      string
    Reachable bool
    Data      map[string]string
    mu        sync.Mutex
}

func (n *Node) Write(key, val string) bool {
    n.mu.Lock()
    defer n.mu.Unlock()
    if !n.Reachable {
        return false
    }
    n.Data[key] = val
    return true
}

type Cluster struct {
    Nodes       []*Node
    N           int
    W           int
    R           int
    HintStorage map[string][]Hint
    mu          sync.Mutex
}

func NewCluster(nodeNames []string, w, r int) *Cluster {
    nodes := make([]*Node, len(nodeNames))
    for i, name := range nodeNames {
        nodes[i] = &Node{
            Name:      name,
            Reachable: true,
            Data:      make(map[string]string),
        }
    }
    return &Cluster{
        Nodes:       nodes,
        N:           len(nodeNames),
        W:           w,
        R:           r,
        HintStorage: make(map[string][]Hint),
    }
}

func (c *Cluster) Write(key, val string) error {
    payload := WritePayload{Key: key, Value: val}
    var wg sync.WaitGroup
    confirmations := 0
    var confMu sync.Mutex

    for _, node := range c.Nodes {
        wg.Add(1)
        go func(n *Node) {
            defer wg.Done()
            if success := n.Write(key, val); success {
                confMu.Lock()
                confirmations++
                confMu.Unlock()
            }
        }(node)
    }
    wg.Wait()

    if confirmations >= c.W {
        fmt.Printf("Strict write quorum met: %d/%d confirmations\n", confirmations, c.W)
        return nil
    }

    fmt.Printf("Strict write quorum failed (%d/%d). Attempting Sloppy Quorum...\n", confirmations, c.W)

    activeWrites := confirmations
    for _, node := range c.Nodes {
        if activeWrites >= c.W {
            break
        }

        node.mu.Lock()
        isReachable := node.Reachable
        node.mu.Unlock()

        if !isReachable {
            for _, backupNode := range c.Nodes {
                if backupNode.Name == node.Name {
                    continue
                }
                backupNode.mu.Lock()
                backupReachable := backupNode.Reachable
                backupNode.mu.Unlock()

                if backupReachable {
                    c.mu.Lock()
                    c.HintStorage[backupNode.Name] = append(c.HintStorage[backupNode.Name], Hint{
                        TargetNode: node.Name,
                        Payload:    payload,
                        Timestamp:  time.Now(),
                    })
                    c.mu.Unlock()

                    fmt.Printf("Stored hint on backup node %s for target offline node %s\n", backupNode.Name, node.Name)
                    activeWrites++
                    break
                }
            }
        }
    }

    if activeWrites >= c.W {
        fmt.Printf("Sloppy write quorum met: %d/%d confirmations (including hints)\n", activeWrites, c.W)
        return nil
    }

    return fmt.Errorf("write failed: failed to satisfy sloppy quorum (%d/%d)", activeWrites, c.W)
}

func (c *Cluster) RecoverNode(nodeName string) {
    var targetNode *Node
    for _, node := range c.Nodes {
        if node.Name == nodeName {
            targetNode = node
            break
        }
    }
    if targetNode == nil {
        return
    }

    targetNode.mu.Lock()
    targetNode.Reachable = true
    targetNode.mu.Unlock()
    fmt.Printf("Node %s has recovered and is online\n", nodeName)

    c.mu.Lock()
    defer c.mu.Unlock()

    for backupName, hints := range c.HintStorage {
        var activeHints []Hint
        for _, hint := range hints {
            if hint.TargetNode == nodeName {
                success := targetNode.Write(hint.Payload.Key, hint.Payload.Value)
                if success {
                    fmt.Printf("Replayed hint from %s to %s for key: %s\n", backupName, nodeName, hint.Payload.Key)
                } else {
                    activeHints = append(activeHints, hint)
                }
            } else {
                activeHints = append(activeHints, hint)
            }
        }
        c.HintStorage[backupName] = activeHints
    }
}

package main

import (
    "context"
    "fmt"
    "sync"
)

type Row struct {
    ID    int
    Value string
    Age   int
}

type ShardConnection interface {
    Query(ctx context.Context, sql string, args ...interface{}) ([]Row, error)
    Exec(ctx context.Context, sql string, args ...interface{}) error
}

type MockShard struct {
    ID   int
    Data []Row
}

func (m *MockShard) Query(ctx context.Context, sql string, args ...interface{}) ([]Row, error) {
    var minAge, maxAge int
    fmt.Sscanf(sql, "SELECT * FROM users WHERE age BETWEEN %d AND %d", &minAge, &maxAge)

    var res []Row
    for _, row := range m.Data {
        if row.Age >= minAge && row.Age <= maxAge {
            res = append(res, row)
        }
    }
    return res, nil
}

func (m *MockShard) Exec(ctx context.Context, sql string, args ...interface{}) error {
    row := args[0].(Row)
    m.Data = append(m.Data, row)
    return nil
}

type Router struct {
    mu          sync.RWMutex
    Shards      map[int]ShardConnection
    IsMigrating bool
    NewShards   map[int]ShardConnection
}

func (r *Router) ResolveShardsForRange(minAge, maxAge int) []int {
    var shardIDs []int
    if minAge <= 30 {
        shardIDs = append(shardIDs, 0)
    }
    if minAge <= 60 && maxAge >= 31 {
        shardIDs = append(shardIDs, 1)
    }
    if maxAge >= 61 {
        shardIDs = append(shardIDs, 2)
    }
    return shardIDs
}

func (r *Router) ScatterGatherQuery(ctx context.Context, minAge, maxAge int) ([]Row, error) {
    shardIDs := r.ResolveShardsForRange(minAge, maxAge)

    r.mu.RLock()
    defer r.mu.RUnlock()

    var wg sync.WaitGroup
    resultChan := make(chan []Row, len(shardIDs))
    errChan := make(chan error, len(shardIDs))

    sql := fmt.Sprintf("SELECT * FROM users WHERE age BETWEEN %d AND %d", minAge, maxAge)

    for _, shardID := range shardIDs {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            shard, exists := r.Shards[id]
            if !exists {
                errChan <- fmt.Errorf("shard %d not configured", id)
                return
            }
            rows, err := shard.Query(ctx, sql)
            if err != nil {
                errChan <- err
                return
            }
            resultChan <- rows
        }(shardID)
    }

    wg.Wait()
    close(resultChan)
    close(errChan)

    if len(errChan) > 0 {
        return nil, <-errChan
    }

    var allRows []Row
    for rows := range resultChan {
        allRows = append(allRows, rows...)
    }

    return allRows, nil
}

func (r *Router) Write(ctx context.Context, shardKey int, row Row) error {
    r.mu.RLock()
    defer r.mu.RUnlock()

    shardID := shardKey % len(r.Shards)
    shard, exists := r.Shards[shardID]
    if !exists {
        return fmt.Errorf("target shard %d not found", shardID)
    }

    err := shard.Exec(ctx, "INSERT INTO users (id, value, age) VALUES ($1, $2, $3)", row)
    if err != nil {
        return err
    }

    if r.IsMigrating {
        newShardID := shardKey % len(r.NewShards)
        if newShard, exists := r.NewShards[newShardID]; exists {
            go func() {
                _ = newShard.Exec(ctx, "INSERT INTO users (id, value, age) VALUES ($1, $2, $3)", row)
            }()
        }
    }

    return nil
}

package main

import (
    "math/rand"
    "sync"
    "time"
)

type NodeState int

const (
    Follower NodeState = iota
    Candidate
    Leader
)

type VoteRequest struct {
    Term         int
    CandidateID  int
    LastLogIndex int
    LastLogTerm  int
}

type VoteResponse struct {
    Term        int
    VoteGranted bool
}

type Heartbeat struct {
    Term     int
    LeaderID int
}

type RaftNode struct {
    mu        sync.Mutex
    id        int
    state     NodeState
    currentTerm int
    votedFor  int
    peers     []int
    votesRecv int

    electionTimeout time.Duration
    electionTimer   *time.Timer
    heartbeatTicker *time.Ticker

    stateChanged chan struct{}
}

func NewRaftNode(id int, peers []int) *RaftNode {
    n := &RaftNode{
        id:           id,
        state:        Follower,
        currentTerm:  0,
        votedFor:     -1,
        peers:        peers,
        stateChanged: make(chan struct{}, 10),
    }
    n.resetElectionTimeout()
    go n.run()
    return n
}

func (n *RaftNode) resetElectionTimeout() {
    rand.Seed(time.Now().UnixNano() + int64(n.id))
    timeout := time.Duration(150+rand.Intn(150)) * time.Millisecond
    n.electionTimeout = timeout
    if n.electionTimer != nil {
        n.electionTimer.Stop()
    }
    n.electionTimer = time.NewTimer(timeout)
}

func (n *RaftNode) run() {
    for {
        n.mu.Lock()
        state := n.state
        n.mu.Unlock()

        switch state {
        case Follower:
            select {
            case <-n.electionTimer.C:
                n.mu.Lock()
                n.transitionToCandidate()
                n.mu.Unlock()
            case <-n.stateChanged:
            }
        case Candidate:
            select {
            case <-n.electionTimer.C:
                n.mu.Lock()
                n.startElection()
                n.mu.Unlock()
            case <-n.stateChanged:
            }
        case Leader:
            select {
            case <-n.heartbeatTicker.C:
                n.sendHeartbeats()
            case <-n.stateChanged:
            }
        }
    }
}

func (n *RaftNode) transitionToCandidate() {
    n.state = Candidate
    n.startElection()
}

func (n *RaftNode) startElection() {
    n.currentTerm++
    n.votedFor = n.id
    n.votesRecv = 1
    n.resetElectionTimeout()

    term := n.currentTerm
    id := n.id

    for _, peer := range n.peers {
        go func(peerID int) {
            req := VoteRequest{
                Term:        term,
                CandidateID: id,
            }
            res := n.sendRequestVote(peerID, req)
            if res.VoteGranted {
                n.mu.Lock()
                defer n.mu.Unlock()
                if n.state == Candidate && n.currentTerm == term {
                    n.votesRecv++
                    if n.votesRecv > (len(n.peers)+1)/2 {
                        n.transitionToLeader()
                    }
                }
            } else if res.Term > term {
                n.mu.Lock()
                defer n.mu.Unlock()
                n.currentTerm = res.Term
                n.transitionToFollower()
            }
        }(peer)
    }
}

func (n *RaftNode) transitionToLeader() {
    n.state = Leader
    if n.electionTimer != nil {
        n.electionTimer.Stop()
    }
    n.heartbeatTicker = time.NewTicker(50 * time.Millisecond)
    n.stateChanged <- struct{}{}
}

func (n *RaftNode) transitionToFollower() {
    n.state = Follower
    n.votedFor = -1
    if n.heartbeatTicker != nil {
        n.heartbeatTicker.Stop()
    }
    n.resetElectionTimeout()
    n.stateChanged <- struct{}{}
}

func (n *RaftNode) HandleHeartbeat(hb Heartbeat) {
    n.mu.Lock()
    defer n.mu.Unlock()

    if hb.Term >= n.currentTerm {
        n.currentTerm = hb.Term
        if n.state != Follower {
            n.transitionToFollower()
        } else {
            n.resetElectionTimeout()
        }
    }
}

func (n *RaftNode) sendRequestVote(peerID int, req VoteRequest) VoteResponse {
    return VoteResponse{Term: n.currentTerm, VoteGranted: true}
}

func (n *RaftNode) sendHeartbeats() {}

