package main

import (
    "fmt"
    "os"
    "os/exec"
    "syscall"
)

// Run this code on a Linux host (or in a VM).
// Execute with: go run main.go run <command> <args>
func main() {
    if len(os.Args) < 2 {
        fmt.Println("Usage: go run main.go run [command] [args...]")
        os.Exit(1)
    }

    switch os.Args[1] {
    case "run":
        runParent()
    case "child":
        runChild()
    default:
        fmt.Printf("Unknown command: %s\n", os.Args[1])
        os.Exit(1)
    }
}

func runParent() {
    fmt.Printf("Running parent process (PID: %d)\n", os.Getpid())

    // Re-execute this binary as a child process, specifying the "child" argument
    cmd := exec.Command("/proc/self/exe", append([]string{"child"}, os.Args[2:]...)...)
    cmd.Stdin = os.Stdin
    cmd.Stdout = os.Stdout
    cmd.Stderr = os.Stderr

    // Configure namespace isolation flags
    cmd.SysProcAttr = &syscall.SysProcAttr{
        Cloneflags: syscall.CLONE_NEWUTS | // New hostnames namespace
            syscall.CLONE_NEWPID | // New process ID space (child will be PID 1)
            syscall.CLONE_NEWNS |  // New mount namespace
            syscall.CLONE_NEWNET,  // New isolated loopback network
    }

    if err := cmd.Run(); err != nil {
        fmt.Printf("Error running child process: %v\n", err)
        os.Exit(1)
    }
}

func runChild() {
    fmt.Printf("Running child container sandbox (PID: %d)\n", os.Getpid())

    // 1. Set hostname inside the isolated UTS namespace
    if err := syscall.Sethostname([]byte("container-sandbox")); err != nil {
        fmt.Printf("Failed to set hostname: %v\n", err)
    }

    // 2. Isolate the mount namespace: mount a private /proc filesystem
    // This ensures commands like `ps` only see processes in this container
    if err := syscall.Mount("proc", "/proc", "proc", 0, ""); err != nil {
        fmt.Printf("Failed to mount /proc: %v\n", err)
    }

    // 3. Execute the target program (e.g. /bin/sh)
    userCmd := os.Args[2]
    userArgs := os.Args[3:]

    cmd := exec.Command(userCmd, userArgs...)
    cmd.Stdin = os.Stdin
    cmd.Stdout = os.Stdout
    cmd.Stderr = os.Stderr

    if err := cmd.Run(); err != nil {
        fmt.Printf("Error executing user command: %v\n", err)
    }

    // Unmount proc before exiting to clean up
    syscall.Unmount("/proc", 0)
}

package main

import (
    "context"
    "log"
    "net/http"
    "net/http/httputil"
    "net/url"
    "sync"
    "sync/atomic"
    "time"
)

type Backend struct {
    URL          *url.URL
    Alive        bool
    mux          sync.RWMutex
    ReverseProxy *httputil.ReverseProxy
}

func (b *Backend) SetAlive(alive bool) {
    b.mux.Lock()
    b.Alive = alive
    b.mux.Unlock()
}

func (b *Backend) IsAlive() bool {
    b.mux.RLock()
    defer b.mux.RUnlock()
    return b.Alive
}

type ServerPool struct {
    backends []*Backend
    current  uint64
}

func (s *ServerPool) AddBackend(backend *Backend) {
    s.backends = append(s.backends, backend)
}

func (s *ServerPool) NextIndex() int {
    return int(atomic.AddUint64(&s.current, 1) % uint64(len(s.backends)))
}

func (s *ServerPool) GetNextPeer() *Backend {
    n := len(s.backends)
    for i := 0; i < n; i++ {
        idx := s.NextIndex()
        if s.backends[idx].IsAlive() {
            return s.backends[idx]
        }
    }
    return nil
}

func (s *ServerPool) HealthCheck() {
    for _, b := range s.backends {
        status := b.isAlive()
        b.SetAlive(status)
        if !status {
            log.Printf("Backend %s is DOWN", b.URL.String())
        }
    }
}

func (b *Backend) isAlive() bool {
    client := http.Client{
        Timeout: 2 * time.Second,
    }
    resp, err := client.Get(b.URL.String() + "/health")
    if err != nil {
        return false
    }
    defer resp.Body.Close()
    return resp.StatusCode == http.StatusOK
}

func main() {
    serverPool := &ServerPool{}

    targets := []string{
        "http://localhost:8081",
        "http://localhost:8082",
        "http://localhost:8083",
    }

    for _, target := range targets {
        targetURL, _ := url.Parse(target)
        proxy := httputil.NewSingleHostReverseProxy(targetURL)

        backend := &Backend{
            URL:          targetURL,
            Alive:        true,
            ReverseProxy: proxy,
        }
        serverPool.AddBackend(backend)
    }

    go func() {
        ticker := time.NewTicker(10 * time.Second)
        for range ticker.C {
            serverPool.HealthCheck()
        }
    }()

    frontendHandler := func(w http.ResponseWriter, r *http.Request) {
        peer := serverPool.GetNextPeer()
        if peer != nil {
            peer.ReverseProxy.ServeHTTP(w, r)
            return
        }
        http.Error(w, "Service Unavailable", http.StatusServiceUnavailable)
    }

    server := http.Server{
        Addr:    ":8080",
        Handler: http.HandlerFunc(frontendHandler),
    }

    log.Fatal(server.ListenAndServe())
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <sys/epoll.h>

#define MAX_EVENTS 64
#define PORT 8080
#define BUFFER_SIZE 1024

/* Set socket descriptor to non-blocking mode */
int make_socket_non_blocking(int sfd) {
    int flags = fcntl(sfd, F_GETFL, 0);
    if (flags == -1) {
        perror("fcntl F_GETFL");
        return -1;
    }
    flags |= O_NONBLOCK;
    if (fcntl(sfd, F_SETFL, flags) == -1) {
        perror("fcntl F_SETFL");
        return -1;
    }
    return 0;
}

int main() {
    int listen_fd, epoll_fd;
    struct sockaddr_in address;
    int opt = 1;

    /* 1. Create a raw TCP socket */
    listen_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (listen_fd == -1) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    /* 2. Enable SO_REUSEADDR socket option to reuse port immediately */
    if (setsockopt(listen_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) == -1) {
        perror("setsockopt SO_REUSEADDR failed");
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    /* 3. Bind socket to target address and port */
    if (bind(listen_fd, (struct sockaddr *)&address, sizeof(address)) == -1) {
        perror("bind failed");
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    /* 4. Configure socket as non-blocking */
    if (make_socket_non_blocking(listen_fd) == -1) {
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    /* 5. Listen for incoming connections (SYN backlog capacity: 128) */
    if (listen(listen_fd, 128) == -1) {
        perror("listen failed");
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    /* 6. Initialize epoll instance */
    epoll_fd = epoll_create1(0);
    if (epoll_fd == -1) {
        perror("epoll_create1 failed");
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    struct epoll_event event;
    struct epoll_event events[MAX_EVENTS];

    event.data.fd = listen_fd;
    event.events = EPOLLIN | EPOLLET; /* Edge-triggered read monitor */

    /* 7. Register listen socket with epoll */
    if (epoll_ctl(epoll_fd, EPOLL_CTL_ADD, listen_fd, &event) == -1) {
        perror("epoll_ctl add listen_fd failed");
        close(listen_fd);
        close(epoll_fd);
        exit(EXIT_FAILURE);
    }

    /* 8. Execute high-performance event loop */
    while (1) {
        int n = epoll_wait(epoll_fd, events, MAX_EVENTS, -1);
        for (int i = 0; i < n; i++) {
            if ((events[i].events & EPOLLERR) ||
                (events[i].events & EPOLLHUP) ||
                (!(events[i].events & EPOLLIN))) {
                /* Handle error or socket disconnection */
                fprintf(stderr, "epoll error on fd %d\n", events[i].data.fd);
                close(events[i].data.fd);
                continue;
            }

            if (listen_fd == events[i].data.fd) {
                /* Handle new incoming connection requests */
                while (1) {
                    struct sockaddr in_addr;
                    socklen_t in_len = sizeof(in_addr);
                    int infd = accept(listen_fd, &in_addr, &in_len);
                    if (infd == -1) {
                        if ((errno == EAGAIN) || (errno == EWOULDBLOCK)) {
                            /* All connections in backlog accepted */
                            break;
                        }
                        perror("accept failed");
                        break;
                    }

                    if (make_socket_non_blocking(infd) == -1) {
                        close(infd);
                        continue;
                    }

                    event.data.fd = infd;
                    event.events = EPOLLIN | EPOLLET; /* Edge-triggered read monitoring */
                    if (epoll_ctl(epoll_fd, EPOLL_CTL_ADD, infd, &event) == -1) {
                        perror("epoll_ctl add client fd failed");
                        close(infd);
                    }
                }
            } else {
                /* Process data ready to read on existing connection */
                int client_fd = events[i].data.fd;
                char buf[BUFFER_SIZE];
                int close_conn = 0;

                while (1) {
                    ssize_t count = read(client_fd, buf, sizeof(buf));
                    if (count == -1) {
                        if (errno != EAGAIN && errno != EWOULDBLOCK) {
                            perror("read error");
                            close_conn = 1;
                        }
                        break;
                    } else if (count == 0) {
                        /* EOF, client closed connection */
                        close_conn = 1;
                        break;
                    }

                    /* Echo the read bytes back to the client socket */
                    ssize_t written = write(client_fd, buf, count);
                    if (written == -1) {
                        perror("write error");
                        close_conn = 1;
                        break;
                    }
                }

                if (close_conn) {
                    close(client_fd);
                }
            }
        }
    }
    close(listen_fd);
    close(epoll_fd);
    return 0;
}

