package main

import (
    "crypto/sha1"
    "encoding/base64"
    "errors"
    "fmt"
    "io"
    "net"
    "net/http"
)

const wsGUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"

func PerformHandshake(w http.ResponseWriter, r *http.Request) (net.Conn, error) {
    if r.Header.Get("Upgrade") != "websocket" || r.Header.Get("Connection") != "Upgrade" {
        http.Error(w, "Not a WebSocket upgrade request", http.StatusBadRequest)
        return nil, errors.New("invalid headers")
    }

    key := r.Header.Get("Sec-WebSocket-Key")
    if key == "" {
        http.Error(w, "Missing Sec-WebSocket-Key", http.StatusBadRequest)
        return nil, errors.New("missing key")
    }

    hasher := sha1.New()
    hasher.Write([]byte(key + wsGUID))
    acceptKey := base64.StdEncoding.EncodeToString(hasher.Sum(nil))

    hijacker, ok := w.(http.Hijacker)
    if !ok {
        http.Error(w, "Hijacking not supported", http.StatusInternalServerError)
        return nil, errors.New("hijack unsupported")
    }
    conn, bufrw, err := hijacker.Hijack()
    if err != nil {
        return nil, err
      }

    bufrw.WriteString("HTTP/1.1 101 Switching Protocols\r\n")
    bufrw.WriteString("Upgrade: websocket\r\n")
    bufrw.WriteString("Connection: Upgrade\r\n")
    bufrw.WriteString("Sec-WebSocket-Accept: " + acceptKey + "\r\n\r\n")
    bufrw.Flush()

    return conn, nil
}

type WSFrame struct {
    Fin     bool
    Opcode  byte
    Masked  bool
    Payload []byte
}

func ReadFrame(r io.Reader) (*WSFrame, error) {
    header := make([]byte, 2)
    _, err := io.ReadFull(r, header)
    if err != nil {
        return nil, err
    }

    fin := (header[0] & 0x80) != 0
    opcode := header[0] & 0x0F

    masked := (header[1] & 0x80) != 0
    payloadLen := int(header[1] & 0x7F)

    var actualLen int64
    if payloadLen == 126 {
        extLen := make([]byte, 2)
        if _, err := io.ReadFull(r, extLen); err != nil {
            return nil, err
        }
        actualLen = int64(extLen[0])<<8 | int64(extLen[1])
    } else if payloadLen == 127 {
        extLen := make([]byte, 8)
        if _, err := io.ReadFull(r, extLen); err != nil {
            return nil, err
        }
        actualLen = 0
        for i := 0; i < 8; i++ {
            actualLen = (actualLen << 8) | int64(extLen[i])
        }
    } else {
        actualLen = int64(payloadLen)
    }

    var maskingKey []byte
    if masked {
        maskingKey = make([]byte, 4)
        if _, err := io.ReadFull(r, maskingKey); err != nil {
            return nil, err
        }
    }

    payload := make([]byte, actualLen)
    if _, err := io.ReadFull(r, payload); err != nil {
        return nil, err
    }

    if masked {
        for i := 0; i < len(payload); i++ {
            payload[i] ^= maskingKey[i%4]
        }
    }

    return &WSFrame{
        Fin:     fin,
        Opcode:  opcode,
        Masked:  masked,
        Payload: payload,
    }, nil
}
